"""Build the standalone, illustrated Thai desktop user manual from reviewed screenshots."""
from pathlib import Path
import base64, html, re

ROOT = Path(__file__).resolve().parent
OUT = ROOT / 'AdaBarprint-คู่มือการใช้งาน.html'
old = OUT.read_text(encoding='utf-8')
db_match = re.search(r'<section class="card" id="sec-database-location">.*?</section>', old, re.S)
if db_match:
    (ROOT / 'manual-assets/database-location.html').write_text(db_match.group(), encoding='utf-8')
db = re.sub(r'(?m)[ \t]+$', '', (ROOT / 'manual-assets/database-location.html').read_text(encoding='utf-8'))
chapters = []
def section(key, title, body):
    chapters.append((key,title,body))
def p(text): return '<p>'+text+'</p>'
def note(text): return '<aside class="note">'+text+'</aside>'
def steps(items): return '<ol class="steps">'+''.join('<li>'+s+'</li>' for s in items)+'</ol>'
def shot(name, title, points):
    data=base64.b64encode((ROOT/'manual-assets'/f'{name}.png').read_bytes()).decode()
    marks=''.join(f'<span class="pin" style="left:{x}%;top:{y}%" aria-hidden="true">{i}</span>' for i,(x,y,_) in enumerate(points,1))
    return f'<figure><div class="screen"><img src="data:image/jpeg;base64,{data}" alt="{html.escape(title)}" loading="lazy">{marks}</div><figcaption>{title} · หมายเลขเริ่มใหม่ในแต่ละภาพ</figcaption></figure>'+steps([s for _,_,s in points])

section('start','1. ติดตั้งและเปิดโปรแกรมครั้งแรก',
 p('คู่มือนี้ใช้กับ <strong>AdaBarprint รุ่นเดสก์ท็อปสำหรับ Windows</strong> เริ่มเปิดจากไอคอนโปรแกรมหลังติดตั้งชุด EXE ภาพประกอบแสดงพื้นที่ทำงานภายในโปรแกรม ชื่อสินค้า ผู้ใช้ เครื่องพิมพ์ และค่าการเชื่อมต่อในภาพเป็นตัวอย่าง ให้ใช้ค่าของสาขาที่ติดตั้งจริง')+
 steps(['รับไฟล์ติดตั้ง AdaBarprint จากทีมติดตั้ง ปิดโปรแกรมรุ่นเดิมก่อนอัปเดต แล้วเปิดไฟล์ติดตั้ง EXE และทำตามหน้าต่างติดตั้งจนเสร็จ','เปิด <strong>AdaBarprint</strong> จากทางลัดบนเดสก์ท็อปหรือเมนู Start ของ Windows จะพบหน้าเข้าสู่ระบบ','เครื่องใหม่ให้กด <strong>ตั้งค่าแหล่งข้อมูล</strong> ก่อน เพื่อให้โปรแกรมมีข้อมูลสินค้าและผู้ใช้ ถ้าทีมติดตั้งตั้งค่าไว้แล้ว ข้ามไปบทเข้าสู่ระบบได้','เตรียมพาธฐานสินค้า หรือ URL และ API Key ของ API2PSMaster พร้อมรหัสตัวแทน สาขา และเครื่องจากผู้ดูแล รวมถึงติดตั้งไดรเวอร์เครื่องพิมพ์ที่ต้องใช้บน Windows'])+
 note('ติดตั้งใหม่ไม่จำเป็นต้องคัดลอกฐานข้อมูลทั้งสองไฟล์มาจากเครื่องอื่น: โปรแกรมสร้างฐานตั้งค่าของตัวเอง ส่วน Standalone ดาวน์โหลดข้อมูลมาสร้างฐานสินค้าได้ ดูตำแหน่งไฟล์ในบทถัดไป')+
 shot('21-login','หน้าแรกหลังเปิด AdaBarprint',[(93,8,'<strong>ตั้งค่าแหล่งข้อมูล</strong> — เริ่มตรงนี้สำหรับเครื่องใหม่'),(59,25,'<strong>รหัสผู้ใช้ / เลือกผู้ใช้</strong> — ใช้บัญชีของสาขาที่ตั้งค่าไว้'),(59,41,'<strong>รหัสผ่านหรือ PIN</strong> — เลือกวิธีเข้าสู่ระบบที่เปิดใช้ แล้วกรอกรหัสของผู้ใช้'),(59,56,'<strong>เข้าสู่ระบบ (F10)</strong> — เมื่อข้อมูลถูกต้องจะเข้าสู่หน้าพิมพ์ป้าย')]))

